code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s1[1000], s2[1000];
    if (scanf("%s %s", s1, s2) == 2) {
        int i = 0;
        while (s1[i] && s2[i] && s1[i] == s2[i]) i++;
        if (i == 0) puts("-1");
        else { s1[i] = '\0'; puts(s1); }
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    string s1, s2; if (cin >> s1 >> s2) {
        size_t i = 0;
        while (i < s1.length() && i < s2.length() && s1[i] == s2[i]) i++;
        if (i == 0) cout << "-1\n";
        else cout << s1.substr(0, i) << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s1 = sc.next(), s2 = sc.next();
            int i = 0;
            while (i < s1.length() && i < s2.length() && s1.charAt(i) == s2.charAt(i)) i++;
            if (i == 0) System.out.println("-1");
            else System.out.println(s1.substring(0, i));
        }
    }
}

code.Python3:
import sys
def main():
    lines = [l.strip() for l in sys.stdin.read().splitlines() if l.strip()]
    if len(lines) >= 2:
        s1, s2 = lines[0], lines[1]
        p = []
        for c1, c2 in zip(s1, s2):
            if c1 == c2: p.append(c1)
            else: break
        print("".join(p) if p else "-1")
if __name__ == "__main__": main()

