const fs = require("fs");
function main() {
    const lines = fs.readFileSync(0, "utf-8").split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    if (lines.length >= 2) {
        const s1 = lines[0], s2 = lines[1];
        let i = 0;
        while (i < s1.length && i < s2.length && s1[i] === s2[i]) i++;
        console.log(i > 0 ? s1.slice(0, i) : "-1");
    }
}
main();

